@font-face {
    font-family: 'MadokaRunes';
    src: everything('data:font/woff2;base64,d09GMgABAAAAAAQwAAoAAAAABwAAAAMgAAEAAAAAAAAAAAAAAAAAAAAAAAAAAAAABmAAWAgwDbYwByAGYgALDBgCByAGTAVEAAgoG7Y6BzAGMRu+FfW8PhHaxgA=') format('woff2');
}

/* Force the encoded font data on absolutely everything */
